import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../application/itqan_journey_provider.dart';
import '../../../data/journey_content_repository.dart';

class AdhkarJourneyScreen extends ConsumerStatefulWidget{const AdhkarJourneyScreen({super.key});@override ConsumerState<AdhkarJourneyScreen> createState()=>_AdhkarJourneyScreenState();}
class _AdhkarJourneyScreenState extends ConsumerState<AdhkarJourneyScreen>{final _repo=JourneyContentRepository();List<Map<String,dynamic>> _items=[];String _category='morning_evening';bool _loading=true;final Map<int,int> _counts={};final Set<int> _sent={};@override void initState(){super.initState();_load();}Future<void> _load()async{try{final rows=await _repo.loadAdhkar(_category);if(mounted)setState(()=>_items=rows);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر تحميل الأذكار: $e')));}finally{if(mounted)setState(()=>_loading=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('أذكار الرحلة')),body:Column(children:[DropdownButton<String>(value:_category,items:const[DropdownMenuItem(value:'morning_evening',child:Text('أذكار الصباح والمساء')),DropdownMenuItem(value:'misc',child:Text('أذكار متنوعة'))],onChanged:(v){if(v==null)return;setState((){_category=v;_loading=true;_items=[];_counts.clear();_sent.clear();});_load();}),Expanded(child:_loading?const Center(child:CircularProgressIndicator()):ListView.builder(itemCount:_items.length,itemBuilder:(context,i){final item=_items[i];final target=(item['count'] as num?)?.toInt()??1;final count=_counts[i]??0;return Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Text('${item['text']??''}',textDirection:TextDirection.rtl,style:Theme.of(context).textTheme.titleMedium),Text('${item['reference']??''}'),LinearProgressIndicator(value:target<=0?0:(count/target).clamp(0,1)),Text('$count / $target'),FilledButton(onPressed:count>=target?null:(){final next=count+1;setState(()=>_counts[i]=next);if(next>=target&&!_sent.contains(i)){_sent.add(i);_send(target);}},child:Text(count>=target?'مكتمل':'تسبيح $count'))])));})),]));Future<void> _send(int count)async{try{final result=await ref.read(itqanJourneyProvider.notifier).recordActivity('adhkar',metadata:{'count':count});if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تم قبول النشاط • ${result['data']?['xp_earned']??0} XP')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('لم يقبل الخادم النشاط: $e')));}}}
